examples.validationRules:
var read = function (name) {
  return api.getValue(name);
};
var lookupCode = function (value) {
  if (value === null || value === undefined || value === '') {
    return '';
  }
  if (typeof value === 'object') {
    return String(value.code || value._code || value.name || value.value || value.description || value._id || '').toLowerCase();
  }
  return String(value).toLowerCase();
};
var empty = function (value) {
  return value === null || value === undefined || String(value).trim() === '';
};
var numberValue = function (value) {
  if (empty(value)) {
    return null;
  }
  return Number(String(value).replace(',', '.'));
};
var type = lookupCode(read('aggregation_type'));
var threshold = read('threshold');
var n = read('n');
if (type === '' || type === 'all' || type === 'any') {
  return empty(threshold) && empty(n) ? true : 'aggregation_type must match its parameters: all/any use no threshold or n, threshold requires threshold 0..100 and empty n, n_of_m requires n >= 1 and empty threshold.';
}
if (type === 'threshold') {
  var thresholdValue = numberValue(threshold);
  return thresholdValue !== null && thresholdValue >= 0 && thresholdValue <= 100 && empty(n) ? true : 'aggregation_type must match its parameters: all/any use no threshold or n, threshold requires threshold 0..100 and empty n, n_of_m requires n >= 1 and empty threshold.';
}
if (type === 'n_of_m') {
  var nValue = numberValue(n);
  return nValue !== null && Math.floor(nValue) === nValue && nValue >= 1 && empty(threshold) ? true : 'aggregation_type must match its parameters: all/any use no threshold or n, threshold requires threshold 0..100 and empty n, n_of_m requires n >= 1 and empty threshold.';
}
return true;

var value = api.getValue('sla_target');
if (value === null || value === undefined || String(value).trim() === '') {
  return true;
}
var parsed = Number(String(value).replace(',', '.'));
return parsed >= 0 && parsed <= 100 ? true : 'sla_target, when filled, must be a percentage from 0 to 100. Use 99.9 for 99.9%, not 0.999.';

var value = api.getValue('priority');
if (value === null || value === undefined || String(value).trim() === '') {
  return true;
}
var parsed = Number(String(value));
return Math.floor(parsed) === parsed && parsed >= 1 && parsed <= 100 ? true : 'priority must be an integer from 1 to 100.';
